import * as D from './core.js';
import {DemoStore} from './storage.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('hu-HU'), dateLabel=d=>new Date(d).toLocaleDateString('hu-HU',{month:'long',day:'numeric'});
const store=new DemoStore();let state=D.freshState(),catalog=[],filters={},limit=12,advanced=false,accountTab='overview',adminQuery='',modalKind='',bookingDraft=null,adImages=[],toastTimer,searchTimer,busy=false;
const user=()=>D.currentUser(state), all=()=>D.profilesWithState(catalog,state), getProfile=id=>all().find(p=>p.id===id);
const statusText={approved:'Jóváhagyva · demó',pending:'Ellenőrzésre vár · demó',rejected:'Elutasítva · demó',suspended:'Felfüggesztve · demó',confirmed:'Visszaigazolva · szimulált',requested:'Kérelem · szimulált',cancelled:'Lemondva · visszatérítve',completed:'Teljesítve · szimulált'};
const roleText={customer:'Regisztrált ügyfél',advertiser:'Hirdető',admin:'Adminisztrátor'};
const options=(values,selected='',blank='Mindegy')=>`${blank!==null?`<option value="">${esc(blank)}</option>`:''}${values.map(v=>{const val=typeof v==='object'?v.value:v,label=typeof v==='object'?v.label:v;return `<option value="${esc(val)}" ${String(val)===String(selected)?'selected':''}>${esc(label)}</option>`;}).join('')}`;
const field=(name,label,type='text',value='',extra='')=>`<div class="field"><label for="${esc(name)}">${label}</label><input id="${esc(name)}" name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const selectField=(name,label,values,value='',blank='Válassz')=>`<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${options(values,value,blank)}</select></div>`;
const empty=(title,text,action='discover',label='Felfedezem a kollekciót')=>`<div class="empty"><div class="serif">${esc(title)}</div><p>${esc(text)}</p>${action?`<button data-action="${action}" class="outline">${label} ↗</button>`:''}</div>`;
const button=(action,label,id='',cls='')=>`<button data-action="${action}" ${id?`data-id="${esc(id)}"`:''} class="${cls}">${label}</button>`;
function toast(text,error=false){const el=$('#toast');el.textContent=text;el.className=`visible ${error?'danger':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',4500);}
function showError(error){const e=$('#modal-error');if(e){e.textContent=error.message;e.focus();}else toast(error.message,true);}
function modal(title,html,kind='generic') {modalKind=kind;$('#modal-content').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="close" data-action="close" aria-label="Ablak bezárása">×</button></div><div class="modal-body">${html}<p id="modal-error" class="error" role="alert" tabindex="-1"></p></div>`;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function close(){ $('#modal').close();modalKind='';bookingDraft=null;}
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function change(fn,{render=true,message=''}={}){if(busy)throw new Error('Az előző művelet mentése még folyamatban van.');busy=true;document.body.setAttribute('aria-busy','true');try{const r=await store.mutate(fn);state=r.state;updateHeader();if(render)renderPage();if(message)toast(message);return r.result;}finally{busy=false;document.body.removeAttribute('aria-busy');}}
function updateHeader(){const u=user();$('#balance').textContent=u?money(u.balance):'25 000';$('#fav-count').textContent=state.favorites.length;$('#login-button').textContent=u?`${u.name.split(' ')[0]} ↗`:'Belépés ↗';const notices=state.notifications.filter(n=>n.userId===u?.id&&!n.read);$('#notice-count').classList.toggle('hidden',!notices.length);}
function route(){return location.hash.replace('#','')||'discover';}
function navigate(r){if(route()===r)renderPage();else location.hash=r;}
function renderPage(){if(!catalog.length)return;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===`#${route()}`));const pages={discover:renderDiscover,favorites:renderFavorites,membership:renderMembership,account:renderAccount,recent:renderRecent,compare:renderComparison};(pages[route()]??renderDiscover)();renderDock();}
function cards(profiles){return `<div class="grid">${profiles.map(card).join('')}</div>`;}
function card(p){const today=new Date().toISOString().slice(0,10);return `<article class="card"><div class="card-visual"><button class="card-photo-button" data-action="profile" data-id="${p.id}" aria-label="${esc(p.name)} profil megnyitása"><img loading="lazy" decoding="async" src="${esc(p.images[0])}" alt="${esc(p.name)} — ${p.age} éves fiktív digitális karakter"></button>${p.premium?'<span class="card-badge badge">◇ PRIVÉ SELECTION</span>':p.verified?'<span class="card-badge badge">✓ DEMÓELLENŐRZÖTT</span>':''}<button class="favorite-button ${state.favorites.includes(p.id)?'on':''}" data-action="favorite" data-id="${p.id}" aria-label="${esc(p.name)} kedvenc" aria-pressed="${state.favorites.includes(p.id)}">${state.favorites.includes(p.id)?'♥':'♡'}</button><div class="card-status">${D.availableSlots(p,today,state.bookings).length?'Ma elérhető · demó':'Tervezhető program · demó'}</div></div><div class="card-content"><div class="card-title"><button data-action="profile" data-id="${p.id}">${esc(p.name)}</button><span class="rating" aria-label="Szimulált értékelés ${p.rating}">★ ${p.rating.toFixed(1)}</span></div><div class="location">⌖ ${esc(p.city)} · ${esc(p.district)} &nbsp; / &nbsp; ${p.age} éves</div><div class="card-tags">${p.categories.slice(0,2).map(c=>`<span class="tag">${esc(c)}</span>`).join('')}</div><div class="card-bottom"><span class="price">${money(p.price)} kr <small>/ óra · virtuális</small></span><button data-action="profile" data-id="${p.id}">Profil megtekintése ↗</button></div><label class="check compare-check"><input type="checkbox" data-compare="${p.id}" ${state.compare.includes(p.id)?'checked':''}> Összehasonlítás</label><div class="card-demo">Fiktív 21+ karakter · szimulált értékelés</div></div></article>`;}
function hero(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">EXKLUZÍV KARAKTEREK. KIVÉTELES ÉLMÉNYEK.</div><h1>A találkozás művészete.<br><i>A választás szabadsága.</i></h1><p>Fedezd fel a kifinomult társaság új világát. Válogatott fiktív karakterek, személyre szabott demóélmények.</p><div class="hero-actions">${button('browse','Felfedezem a kollekciót ↗','','gold')}${button('membership','A Privé élmény ◇','','quiet')}</div><div class="hero-note"><span>✓ Minden karakter 21+</span><span>◇ 100% szimulált élmény</span></div></div><div class="hero-art"><img src="./assets/portrait-0.svg#look0" alt="Amélia Velour, fiktív felnőtt digitális karakter" fetchpriority="high"><div class="hero-seal">PRIVÉ<b>◇</b>SELECTION</div><div class="hero-float"><small class="eyebrow">A KOLLEKCIÓ ARCA</small><div class="serif">Amélia Velour <span class="rating">★ 4.3</span></div><small>Budapest · 21 éves · Fiktív karakter</small><div class="margin-top">${button('profile','Ismerd meg Améliát ↗','NP-0001','text-link')}</div></div></div></section><div class="trust-row"><div><b>◇</b><span>216 egyedi karakter<small>Fiktív felnőtt kollekció</small></span></div><div><b>✓</b><span>Átlátható demóprofilok<small>Szimulált ellenőrzés</small></span></div><div><b>⌖</b><span>7 magyar város<small>Fedezd fel a lehetőségeket</small></span></div><div><b>✧</b><span>A diszkréció eleganciája<small>Adatok a böngésződben</small></span></div></div>`;}
function renderDiscover(){const result=D.filterProfiles(all(),{...filters,bookings:state.bookings});$('#main').innerHTML=`${hero()}<section class="section" id="collection"><div class="section-head"><div><div class="eyebrow">VÁLOGATOTT COMPANION KOLLEKCIÓ</div><h2>Találd meg a <i>különlegeset.</i></h2><p>Minden történet más. A következő fejezetet te választod.</p></div>${button('recent','Legutóbb megtekintett ↗','','quiet')}</div><div class="category-row">${button('category','Összes karakter','',''+(!filters.category?'selected':''))}${state.categories.map(c=>button('category',esc(c),c,filters.category===c?'selected':'')).join('')}</div><form id="search-form"><div class="filter-bar"><div class="field"><label for="q">KERESÉS A KOLLEKCIÓBAN</label><input id="q" name="q" value="${esc(filters.q??'')}" placeholder="Név, város vagy hangulat…" autocomplete="off" maxlength="100"><div id="suggestions" class="suggestions" aria-live="polite"></div></div>${selectField('city','VÁROS',[...new Set(catalog.map(p=>p.city))],filters.city??'','Minden város')}${selectField('district','KERÜLET / VÁROSRÉSZ',[...new Set(all().filter(p=>!filters.city||p.city===filters.city).map(p=>p.district))],filters.district??'','Minden városrész')}<button class="gold" type="submit">Keresés ↗</button></div>${advanced?`<div class="advanced"><div class="form-grid four">${field('minAge','Életkor · minimum','number',filters.minAge??21,'min="21" max="70"')}${field('maxAge','Életkor · maximum','number',filters.maxAge??70,'min="21" max="70"')}${field('minPrice','Óradíj · minimum kredit','number',filters.minPrice??0,'min="0" max="100000"')}${field('maxPrice','Óradíj · maximum kredit','number',filters.maxPrice??15000,'min="0" max="100000"')}${field('date','Elérhető ezen a napon','date',filters.date??'',`min="${new Date().toISOString().slice(0,10)}" max="${new Date(Date.now()+30*86400000).toISOString().slice(0,10)}"`)}${selectField('rating','Minimum szimulált értékelés',['4.5','4.7','4.9'],filters.rating??'','Minden értékelés')}<label class="check"><input type="checkbox" name="premium" ${filters.premium?'checked':''}> Csak prémium profilok</label><label class="check"><input type="checkbox" name="verified" ${filters.verified?'checked':''}> Csak demóellenőrzött profilok</label></div></div>`:''}</form><div class="filter-meta"><div><strong>${result.length}</strong> fiktív karakter <span>· 21+</span>${Object.keys(filters).some(k=>filters[k]&&k!=='sort')?` ${button('reset-filters','Szűrők törlése')}`:''}</div><div class="meta-actions">${button('advanced',advanced?'Kevesebb szűrő −':'Részletes szűrők +')}${button('save-search','Keresés mentése ♧')}<label for="sort" class="hidden">Rendezés</label><select id="sort">${options([{value:'recommended',label:'Ajánlott sorrend'},{value:'price-asc',label:'Ár: növekvő'},{value:'price-desc',label:'Ár: csökkenő'},{value:'rating',label:'Legjobb demóértékelés'},{value:'newest',label:'Legújabb profilok'},{value:'name',label:'Név szerint'}],filters.sort??'recommended',null)}</select></div></div>${state.savedSearches.length?`<div class="saved-row">${state.savedSearches.map((s,i)=>`${button('saved-search',esc(s.name),String(i))}${button('delete-search','×',String(i))}`).join('')}</div>`:''}${store.warning?`<div class="notice">${esc(store.warning)}</div>`:''}${result.length?cards(result.slice(0,limit)):empty('Nincs ilyen találat.','Próbálj tágabb kor-, ár- vagy városszűrőt.','reset-filters','Szűrők törlése')}<div class="load-more">${result.length>limit?button('load-more',`További karakterek (${Math.min(12,result.length-limit)}) ↓`):'<small>A válogatás végére értél.</small>'}<small>${Math.min(result.length,limit)} / ${result.length}</small></div>${state.recent.length?`<div class="section-head margin-top"><div><div class="eyebrow">A TE TÖRTÉNETED</div><h2>Visszatérnél <i>hozzájuk?</i></h2></div>${button('recent','Megtekintési előzmények ↗','','quiet')}</div>${cards(state.recent.map(getProfile).filter(p=>p&&p.status==='approved').slice(0,4))}`:''}<div class="club-banner"><div><div class="eyebrow">PRIVÉ CLUB</div><h2>A kivételes <i>mindennapjaid része.</i></h2><p>Prémium demótagság, virtuális kedvezmények és hűségjutalmak.</p></div><span class="club-symbol">◇</span>${button('membership','Felfedezem a tagságokat ↗','','gold')}</div><div class="feature-columns"><div><div class="number">01 / EGYÉNISÉG</div><h3>Több, mint egy profil.</h3><p>Részletes történetek, egyedi digitális portrék és változatos érdeklődési körök.</p></div><div><div class="number">02 / NYUGALOM</div><h3>Minden lépés átlátható.</h3><p>Virtuális kreditek, világos díjak, demóbizonylatok. Soha nem kérünk bankkártyaadatot.</p></div><div><div class="number">03 / FELFEDEZÉS</div><h3>Válassz saját ritmusodban.</h3><p>Kedvencek, összehasonlítás és mentett keresések — az adatok a saját böngésződben maradnak.</p></div></div></section>`;}
function renderFavorites(){const list=state.favorites.map(getProfile).filter(p=>p&&p.status==='approved');$('#main').innerHTML=`<section class="section"><div class="screen-title"><div class="eyebrow">SAJÁT KOLLEKCIÓD</div><h1>A kedvenceid. <i>A te választásod.</i></h1><p>${list.length} fiktív karakter · Ezen a böngészőn mentett válogatás.</p></div>${list.length?cards(list):empty('Még nincs kedvenced.','A profilokon található szívvel készíthetsz saját válogatást.')}<div class="panel"><h3>Ajánljuk a figyelmedbe</h3><p>A kedvelt kategóriákhoz és városokhoz illő, még nem mentett fiktív profilok.</p>${cards(recommendations().slice(0,4))}</div></section>`;}
function recommendations(){const fav=state.favorites.map(getProfile).filter(Boolean),last=state.recent.map(getProfile).filter(Boolean);const seed=[...fav,...last];return all().filter(p=>p.status==='approved'&&!state.favorites.includes(p.id)).sort((a,b)=>{const score=p=>seed.reduce((n,s)=>n+(s.city===p.city?2:0)+s.categories.filter(c=>p.categories.includes(c)).length,0)+p.rating;return score(b)-score(a);});}
function renderRecent(){const list=state.recent.map(getProfile).filter(p=>p&&p.status==='approved');$('#main').innerHTML=`<section class="section"><div class="section-head"><div><div class="eyebrow">BÖNGÉSZŐBEN TÁROLT ELŐZMÉNYEK</div><h2>Legutóbb <i>megtekintett.</i></h2></div>${button('clear-recent','Előzmények törlése')}</div>${list.length?cards(list):empty('Még nincs megtekintési előzmény.','Nyiss meg egy profilt a kollekcióból.')}<div class="section-head margin-top"><h2>Neked <i>ajánljuk.</i></h2></div>${cards(recommendations().slice(0,4))}</section>`;}
function renderDock(){document.querySelector('.compare-dock')?.remove();if(state.compare.length){const el=document.createElement('div');el.className='compare-dock';el.innerHTML=`<span>◇ ${state.compare.length}/4 karakter kiválasztva</span>${button('compare','Összehasonlítás ↗','','gold')}${button('clear-compare','Törlés','','quiet')}`;document.body.appendChild(el);}}
function renderComparison(){const list=state.compare.map(getProfile).filter(p=>p&&p.status==='approved');$('#main').innerHTML=`<section class="section"><div class="section-head"><div><div class="eyebrow">A RÉSZLETEK SZÁMÍTANAK</div><h2>Profilok <i>egymás mellett.</i></h2></div>${button('clear-compare','Kijelölések törlése')}</div>${list.length?`<div class="table-wrap"><table><thead><tr><th>Összehasonlítás</th>${list.map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${[['Életkor',p=>`${p.age} év`],['Város',p=>`${p.city} / ${p.district}`],['Óradíj',p=>`${money(p.price)} demókredit`],['Stílus',p=>p.style],['Kategóriák',p=>p.categories.join(', ')],['Szimulált értékelés',p=>`★ ${p.rating}`],['Demóellenőrzés',p=>p.verified?'Szimulált · igen':'Szimulált · nincs'],['Prémium',p=>p.premium?'Privé Selection':'Standard']].map(([label,fn])=>`<tr><th>${label}</th>${list.map(p=>`<td>${esc(fn(p))}</td>`).join('')}</tr>`).join('')}<tr><th>Fiktív profil</th>${list.map(p=>`<td>${button('profile','Megnyitás ↗',p.id)} ${button('remove-compare','Eltávolítás',p.id)}</td>`).join('')}</tr></tbody></table></div>`:empty('Válassz legfeljebb négy profilt.','A profilkártyákon jelöld be az Összehasonlítás mezőt.')}</section>`;}
async function openProfile(id,track=true){let p=getProfile(id);if(!p)throw new Error('A profil nem található.');if(p.status!=='approved'&&user()?.role!=='admin'&&p.ownerId!==user()?.id)throw new Error('A profil jelenleg nem elérhető.');if(track)await change(s=>{s.recent=[id,...s.recent.filter(x=>x!==id)].slice(0,20);s.views[id]=(s.views[id]??0)+1;},{render:false});p=getProfile(id);const days=Array.from({length:14},(_,i)=>new Date(Date.now()+i*86400000).toISOString().slice(0,10));modal(esc(p.name),`<div class="profile-layout"><div><img id="gallery-image" class="gallery-main" src="${esc(p.images[0])}" alt="${esc(p.name)} digitális demóportré"><div class="gallery-thumbs">${p.images.map((src,i)=>`<button data-action="gallery" data-id="${p.id}" data-index="${i}" aria-label="${i+1}. demókép megtekintése"><img src="${esc(src)}" alt="${i+1}. fiktív portréváltozat"></button>`).join('')}</div><p class="demo-caption">Saját digitális illusztrációk. Nem valódi személy fotói.</p><div class="profile-facts"><div><span>Megtekintés · demóstatisztika</span><b>${money(p.views+(state.views[id]??0))}</b></div><div><span>Értékelés · szimulált</span><b>★ ${p.rating.toFixed(1)} / 5</b></div></div></div><div class="profile-info"><div class="badge">${p.verified?'✓ DEMÓELLENŐRZÖTT':'◇ FIKTÍV PROFIL'} · ${p.age}+</div><h2>${esc(p.name)}</h2><p>⌖ ${esc(p.city)} · ${esc(p.district)} &nbsp; / &nbsp; ${p.age} éves</p><p>${esc(p.bio)}</p><div class="profile-facts"><div><span>Stílus</span><b>${esc(p.style)}</b></div><div><span>Nyelvek · demó</span><b>${esc(p.languages.join(', '))}</b></div><div class="full"><span>Megjelenés</span><b>${esc(p.appearance)}</b></div></div><div class="card-tags">${p.categories.map(c=>`<span class="tag">${esc(c)}</span>`).join('')}</div><div class="price">${money(p.price)} kr <small>/ óra · virtuális kredit</small></div><div class="modal-actions">${p.status==='approved'?button('book','Demófoglalás indítása ↗',id,'gold'):`<span class="status ${p.status}">${esc(statusText[p.status])}</span>`}${button('favorite',state.favorites.includes(id)?'♥ Mentve':'♡ Kedvenc',id)}${button('message','Demóüzenet',id)}</div><small>Minden program, ellenőrzés és foglalás szimulált. Valódi szolgáltatás nincs.</small></div></div><div class="margin-top"><h3>Demóelérhetőség · következő 14 nap</h3><div class="availability">${days.map(d=>`<div class="${D.availableSlots(p,d,state.bookings).length?'open':''}">${new Date(d+'T12:00:00').toLocaleDateString('hu-HU',{weekday:'short'})}<br>${d.slice(8)}<br>${D.availableSlots(p,d,state.bookings).length?'Elérhető':'Zárva'}</div>`).join('')}</div><p class="demo-caption">14:00–22:00 · A checkoutban a teljes időtartam szabad helyeit ellenőrizzük.</p></div><div class="margin-top"><h3>Értékelések <small>Mind szimulált, nem valódi ügyfélvélemény.</small></h3>${p.reviews.filter(r=>!state.reviewModeration[r.id]).map(r=>`<div class="review"><span class="rating">${'★'.repeat(r.rating)}</span> <small>${esc(r.name)} · Szimulált vélemény</small><p>${esc(r.text)}</p>${button('report-review','Vélemény jelentése',`${p.id}|${r.id}`)}</div>`).join('')||'<p>Még nincs látható demóvélemény.</p>'}</div><div class="modal-actions">${button('report','Profil jelentése',id,'quiet')}${button('verification','Mit jelent az ellenőrzés?','','quiet')}</div>`,'profile');}
function loginModal(register=false){modal(register?'Demófiók létrehozása':'Üdvözlünk a Privé világában',`<div class="notice">Böngészőben tárolt demófiók. Nincs valódi hitelesítés vagy biztonság. Ne használj valódi nevet, e-mailt vagy jelszót!</div><form id="${register?'register-form':'login-form'}"><div class="form-grid">${register?field('name','Fiktív megjelenített név','text','','required maxlength="60"'):''}${field('handle','Demóazonosító','text','','required minlength="3" maxlength="30" autocomplete="off" pattern="[a-zA-Z0-9_-]{3,30}"')}${field('password','Demójelszó (ne a valódit használd)','password','','required minlength="8" maxlength="100" autocomplete="off"')}${register?selectField('role','Demószerepkör',[{value:'customer',label:'Ügyfél'},{value:'advertiser',label:'Hirdető'}],'customer',null):''}${register?'<label class="check full"><input name="adult" type="checkbox" required> Elmúltam 18 éves, és elfogadom a fiktív demószabályokat.</label>':''}</div><div class="modal-actions"><button type="submit" class="gold">${register?'Demófiók létrehozása':'Belépés'} ↗</button>${button(register?'login':'register',register?'Már van demófiókom':'Új demófiókot készítek','','quiet')}</div></form><div class="panel"><h3>Azonnali demóbelépés</h3><p>Próbáld ki a szerepköröket regisztráció nélkül. Ezek szabadon elérhető tesztfiókok.</p><div class="modal-actions">${button('demo-login','Ügyfél','customer')}${button('demo-login','Hirdető','advertiser')}${button('demo-login','Adminisztrátor','admin')}</div></div>`,'login');}
function bookingModal(id){const p=getProfile(id);if(!user()){loginModal();toast('Demófoglaláshoz ügyfélfiók szükséges.');return;}D.requireRole(state,['customer']);if(!p||p.status!=='approved')throw new Error('A profil nem foglalható.');bookingDraft={profileId:id,category:p.categories[0],packageId:'signature',duration:1,date:new Date().toISOString().slice(0,10),time:'',code:''};renderBooking(1);}
function renderBooking(step){const p=getProfile(bookingDraft.profileId);if(!p)throw new Error('A profil nem érhető el.');const steps=`<div class="booking-steps"><span class="${step===1?'active':''}">01 / PROGRAM ÉS IDŐPONT</span><span class="${step===2?'active':''}">02 / ÖSSZESÍTÉS</span><span class="${step===3?'active':''}">03 / SZIMULÁLT FIZETÉS</span></div>`;if(step===1){const d=bookingDraft;const times=D.availableSlots(p,d.date,state.bookings).filter(t=>D.isAvailable(p,d.date,t,Number(d.duration),state.bookings));modal('Egy új demóélmény',`${steps}<div class="notice">${esc(p.name)} · ${p.age} éves fiktív karakter. Nincs valódi foglalás, találkozó vagy fizetés.</div><form id="booking-form"><div class="form-grid">${selectField('category','Programkategória · szimulált',p.categories,d.category,null)}${selectField('packageId','Demócsomag',p.packages.map(x=>({value:x.id,label:`${x.name} (+${money(x.extra)} kr)`})),d.packageId,null)}${selectField('duration','Időtartam',[1,2,3,4].map(n=>({value:n,label:`${n} óra`})),d.duration,null)}${field('date','Demóprogram dátuma','date',d.date,`required min="${new Date().toISOString().slice(0,10)}" max="${new Date(Date.now()+30*86400000).toISOString().slice(0,10)}"`)}${selectField('time','Szabad kezdési időpont',times,d.time,times.length?'Válassz kezdést':'Nincs szabad időpont')}${field('code','Promóciós kód (opcionális)','text',d.code,'maxlength="30" placeholder="PRIVE10"')}</div><p class="demo-caption">Válassz másik napot vagy rövidebb időtartamot, ha nincs szabad időpont. PRIVE10: 10%, WELCOME20: 20% demókedvezmény, ha a kampány aktív.</p><div id="live-quote">${quoteHtml()}</div><div class="modal-actions"><button type="submit" class="gold">Összesítés megtekintése ↗</button>${button('profile','Vissza a profilhoz',p.id,'quiet')}</div></form>`,'booking');}else if(step===2){const q=D.calculate(p,{...bookingDraft,membership:user().membership},state.campaigns);modal('A kiválasztott demóélmény',`${steps}<div class="notice">Minden tétel virtuális. 1 kr = 1 fiktív demókredit, pénzre nem váltható.</div><ul class="summary-list"><li><span>Karakter</span><strong>${esc(p.name)} · ${p.age}+</strong></li><li><span>Program</span><strong>${esc(bookingDraft.category)}</strong></li><li><span>Csomag</span><strong>${esc(q.package)}</strong></li><li><span>Demóidőpont</span><strong>${dateLabel(bookingDraft.date)} · ${bookingDraft.time} · ${q.duration} óra</strong></li></ul>${quoteHtml()}<p class="demo-caption">Pénztárcád: ${money(user().balance)} demókredit. Lemondás esetén teljes virtuális visszatérítés jár, teljesítés előtt.</p><label class="check"><input id="payment-consent" type="checkbox"> Megértettem, hogy szimulált tranzakciót indítok.</label><div class="modal-actions">${button('pay',`${money(q.total)} demókredit szimulált fizetése ↗`,p.id,'gold')}${button('booking-back','Vissza az adatokhoz','','quiet')}</div>`,'booking');}else{const b=bookingDraft.confirmation;const t=state.transactions.find(t=>t.bookingId===b.id&&t.type==='booking');modal('Visszaigazolt szimuláció',`${steps}<div class="empty"><div class="serif">✓ Egy élmény kezdete.</div><p>A fiktív foglalás a demófiókodba került.<br>Valódi szolgáltatás vagy találkozó nem jött létre.</p><span class="badge">SZIMULÁLT · SIKERES</span></div><ul class="summary-list"><li><span>Demóazonosító</span><strong>${esc(b.id.slice(0,12))}</strong></li><li><span>Karakter</span><strong>${esc(b.profileName)}</strong></li><li><span>Időpont</span><strong>${dateLabel(b.date)} · ${b.time}</strong></li><li><span>Virtuális összeg</span><strong>${money(b.total)} kr</strong></li></ul><div class="modal-actions">${button('receipt','Demóbizonylat letöltése',t.id,'gold')}${button('history','Foglalási előzmények ↗')}</div>`,'confirmation');}}
function quoteHtml(){try{const p=getProfile(bookingDraft.profileId),q=D.calculate(p,{...bookingDraft,membership:user()?.membership},state.campaigns);return `<div class="quote"><div class="quote-row"><span>Óradíj × ${q.duration} + csomag</span><span>${money(q.subtotal)} kr</span></div><div class="quote-row"><span>Kedvezmény · ${Math.round(q.discount*100)}%</span><span>−${money(q.saving)} kr</span></div><div class="quote-row total"><span>Virtuális végösszeg</span><span>${money(q.total)} kr</span></div><small>Minden tétel szimulált, valódi pénzmozgás nélkül.</small></div>`;}catch(e){return `<div class="notice error">${esc(e.message)}</div>`;}}
function renderMembership(){const u=user();$('#main').innerHTML=`<section class="section"><div class="screen-title"><div class="eyebrow">PRIVÉ CLUB · SZIMULÁLT TAGSÁGOK</div><h1>Az elegancia <i>belső köre.</i></h1><p>Egyszeri virtuális kreditköltés. Nincs valódi előfizetés vagy ismétlődő terhelés.<br>A tagság ezen a böngészőn, a demó alaphelyzetbe állításáig aktív.</p></div><div class="membership-grid">${D.MEMBERSHIPS.map(m=>`<article class="membership-card"><div class="eyebrow">${m.id==='gold'?'A PRIVÉ AJÁNLATA':'PRIVÉ CLUB'}</div><h2>${m.name}</h2><div class="price">${money(m.price)} kr</div><p>Egyszeri szimulált tagsági díj</p><ul><li>${Math.round(m.discount*100)}% virtuális programkedvezmény</li><li>Promóciós kóddal összevonható</li><li>Hűségpont minden demófoglalásért</li><li>Részletes szimulált előzmények</li></ul>${button('membership-confirm',u?.membership===m.id?'✓ Aktív demótagság':`${m.name} tagság kiválasztása ↗`,m.id,u?.membership===m.id?'outline':'gold')}</article>`).join('')}</div><div class="panel"><h3>A hűséged érték.</h3><p>Minden elköltött 100 demókredit után 1 pont jár. 100 pont = 500 virtuális kredit. Lemondáskor a jóváírt pontokat visszavonjuk.</p><div class="modal-actions"><span class="price">${u?.points??0} pont</span>${button('redeem','100 pont beváltása ↗')}</div></div><div class="notice">A Privé Club kizárólag fiktív demonstráció. A krediteknek, pontoknak és tagságoknak nincs pénzbeli értékük.</div></section>`;}
function renderAccount(){const u=user();if(!u){$('#main').innerHTML=`<section class="section"><div class="screen-title"><div class="eyebrow">SAJÁT PRIVÉ TÉR</div><h1>A történeted <i>itt kezdődik.</i></h1><p>A demófiók csak ezen a böngészőn létezik. Nincs valódi regisztráció vagy hitelesítés.</p></div>${empty('Lépj be a demóba.','Kipróbálhatod az ügyfél, hirdető és adminisztrátor nézetet is.','login','Demóbelépés')}<div class="modal-actions">${button('demo-login','Ügyfél','customer')}${button('demo-login','Hirdető','advertiser')}${button('demo-login','Adminisztrátor','admin')}${button('register','Regisztráció szimulációja','','gold')}</div></section>`;return;}
const tabs=u.role==='admin'?[['overview','Áttekintés'],['moderation','Profilmoderálás'],['reports','Jelentések'],['reviews','Vélemények'],['campaigns','Kampányok és kategóriák'],['finance','Pénzügyi jelentés'],['transactions','Saját pénztárca'],['audit','Auditnapló']]:u.role==='advertiser'?[['overview','Áttekintés'],['ads','Hirdetéseim'],['requests','Foglalási kérelmek'],['analytics','Analitika'],['transactions','Pénztárca'],['messages','Üzenetek']]:[['overview','Áttekintés'],['bookings','Foglalásaim'],['transactions','Pénztárca és előzmények'],['messages','Üzenetek']];if(!tabs.some(t=>t[0]===accountTab))accountTab='overview';
$('#main').innerHTML=`<section class="section"><div class="section-head screen-title"><div><div class="eyebrow">${roleText[u.role].toUpperCase()} · DEMÓDASHBOARD</div><h1>Üdvözlünk, <i>${esc(u.name)}.</i></h1><p>Helyi demófiók · Nincs valódi hitelesítés vagy biztonság.</p></div>${button('logout','Kilépés ↗','','outline')}</div>${store.warning?`<div class="notice">${esc(store.warning)}</div>`:''}<div class="dashboard-nav">${tabs.map(([id,name])=>button('account-tab',name,id,accountTab===id?'selected':'')).join('')}</div>${accountContent(u)}<div class="panel"><h3>Demóadatok és szerepkörök</h3><p>A szerepkörök szabadon kipróbálhatók. A jogosultságok csak a demó működését mutatják be. A kedvencek és keresések ezen a böngészőn közösek; a pénztárca és a foglalások fiókonként különülnek el.</p><div class="modal-actions">${button('demo-login','Ügyfél nézet','customer')}${button('demo-login','Hirdető nézet','advertiser')}${button('demo-login','Admin nézet','admin')}${button('backup','Mentés és visszaállítás')}${button('reset-confirm','Demó alaphelyzetbe állítása','','danger')}</div></div></section>`;}
const ownBookings=u=>state.bookings.filter(b=>u.role==='admin'||b.userId===u.id||(u.role==='advertiser'&&b.advertiserId===u.id));
function stats(items){return `<div class="stats">${items.map(([label,val])=>`<div class="stat"><small>${label}</small><b>${esc(val)}</b></div>`).join('')}</div>`;}
function chart(rows){const max=Math.max(1,...rows.map(r=>r[1]));return `<div class="bar-chart" role="img" aria-label="${esc(rows.map(r=>r.join(': ')).join('; '))}">${rows.map(([label,val])=>`<div class="bar-row"><span>${esc(label)}</span><div class="bar-track"><div class="bar-fill" data-width="${Math.round(val/max*10)}"></div></div><span>${money(val)}</span></div>`).join('')}</div>`;}
function accountContent(u){const bookings=ownBookings(u),transactions=state.transactions.filter(t=>t.userId===u.id),ads=all().filter(p=>p.ownerId===u.id);
if(accountTab==='overview'){return stats([['Virtuális egyenleg',`${money(u.balance)} kr`],['Demóhűségpont',u.points],['Szimulált foglalások',bookings.length],[u.role==='advertiser'?'Saját hirdetések':'Prémium tagság',u.role==='advertiser'?ads.length:(D.MEMBERSHIPS.find(m=>m.id===u.membership)?.name??'Standard')]])+`<div class="split"><div class="panel"><h3>A következő lépésed</h3><p>${u.role==='admin'?'Tekintsd át a beküldött fiktív profilokat és jelentéseket.':u.role==='advertiser'?'Készíts saját fiktív 21+ karaktert, majd küldd be demómoderálásra.':'A kollekcióból választva végigpróbálhatod a virtuális foglalás és fizetés lépéseit.'}</p><div class="modal-actions">${button(u.role==='advertiser'?'new-ad':u.role==='admin'?'account-tab':'discover',u.role==='advertiser'?'Új fiktív hirdetés ↗':u.role==='admin'?'Moderálás megnyitása ↗':'Felfedezés ↗',u.role==='admin'?'moderation':'','gold')}${button('wallet','Pénztárcám')}</div></div><div class="panel"><h3>Demóaktivitás</h3>${chart([['Foglalások',bookings.length],['Tranzakciók',transactions.length],['Üzenetek',state.messages.filter(m=>m.userId===u.id&&m.sender==='user').length],['Kedvencek',state.favorites.length]])}<p class="demo-caption">Saját böngészőaktivitásból számolt, szimulált adatok.</p></div></div>`;}
if(accountTab==='bookings'||accountTab==='requests')return `<div class="panel"><h3>${u.role==='advertiser'?'Beérkező demófoglalások':'A demófoglalásaid'}</h3><p>A foglalások kizárólag szimuláltak. Lemondáskor a teljes kreditösszeget visszatérítjük.</p>${bookingRecords(bookings,u)}</div>`;
if(accountTab==='transactions')return stats([['Demóegyenleg',`${money(u.balance)} kr`],['Tranzakció',transactions.length],['Tagság',u.membership??'Standard'],['Hűségpont',u.points]])+`<div class="modal-actions">${button('wallet','Virtuális feltöltés ↗','','gold')}${button('membership','Demótagságok')}${button('redeem','100 pont beváltása')}</div><div class="panel"><h3>Szimulált pénzügyi előzmények</h3>${transactionTable(transactions)}</div>`;
if(accountTab==='messages')return `<div class="panel"><h3>Szimulált belső üzenetek</h3><p>Az üzenetek nem jutnak el más személyhez vagy szerverre. A válasz automatikusan generált demó.</p>${state.messages.filter(m=>m.userId===u.id).length?[...new Set(state.messages.filter(m=>m.userId===u.id).map(m=>m.profileId))].map(id=>`<div class="record"><h3>${esc(getProfile(id)?.name??'Archív fiktív profil')}</h3><p>${state.messages.filter(m=>m.userId===u.id&&m.profileId===id).length} demóüzenet</p>${getProfile(id)?button('message','Beszélgetés megnyitása ↗',id):''}</div>`).join(''):empty('Még nincs demóbeszélgetés.','Nyiss meg egy profilt, és válaszd a Demóüzenet gombot.')}</div>`;
if(accountTab==='ads')return `<div class="section-head"><h2>Az atelier <i>kollekciója.</i></h2>${button('new-ad','Új fiktív hirdetés +','','gold')}</div>${ads.length?ads.map(p=>`<div class="panel"><div class="record-head"><div><h3>${esc(p.name)} · ${p.age}+</h3><p>${esc(p.city)} · ${money(p.price)} kr/óra · ${p.premium?'Kiemelt demóprofil':'Standard demóprofil'}</p></div><span class="status ${p.status}">${esc(statusText[p.status])}</span></div><div class="record-actions">${button('edit-ad','Szerkesztés és elérhetőség',p.id)}${button('profile','Hirdetés előnézete ↗',p.id)}${button('promote-confirm',p.premium?'✓ Demókiemelés aktív':'Kiemelés · 1 000 kr',p.id)}</div></div>`).join(''):empty('A kollekciód még üres.','Készíts egy fiktív, legalább 21 éves karaktert.','new-ad','Új hirdetés készítése')}`;
if(accountTab==='analytics')return stats([['Saját demóprofilok',ads.length],['Saját profilmegnyitások',ads.reduce((n,p)=>n+(state.views[p.id]??0),0)],['Demófoglalások',bookings.length],['Virtuális forgalom',`${money(bookings.filter(b=>b.status!=='cancelled'&&b.status!=='rejected').reduce((n,b)=>n+b.total,0))} kr`]])+`<div class="panel"><h3>Hirdetéseid teljesítménye · helyi demóadat</h3>${chart(ads.map(p=>[p.name,state.views[p.id]??0]))}${!ads.length?'<p>Még nincs saját hirdetés. Az analitika az új profilokon végzett helyi műveleteket követi.</p>':''}</div>`;
if(accountTab==='moderation'){const profiles=all().filter(p=>!adminQuery||D.fold(p.name+' '+p.status+' '+p.city).includes(D.fold(adminQuery))),pending=all().filter(p=>p.status==='pending');return stats([['Jóváhagyva',all().filter(p=>p.status==='approved').length],['Ellenőrzésre vár',pending.length],['Felfüggesztve',all().filter(p=>p.status==='suspended').length],['Elutasítva',all().filter(p=>p.status==='rejected').length]])+`<div class="panel"><h3>Profilmoderálás · szimulált adminisztráció</h3><form id="admin-search"><div class="form-grid">${field('adminQuery','Név, város vagy státusz','text',adminQuery,'maxlength="100"')}<div class="modal-actions"><button type="submit">Keresés</button>${button('admin-clear','Törlés')}</div></div></form>${[...profiles].sort((a,b)=>(a.status==='pending'?-1:0)-(b.status==='pending'?-1:0)).slice(0,30).map(p=>`<div class="record"><div class="record-head"><div><h3>${esc(p.name)} · ${p.age}+</h3><p>${esc(p.city)} · Fiktív karakter · ${money(p.price)} kr</p></div><span class="status ${p.status}">${esc(statusText[p.status])}</span></div><div class="record-actions">${button('profile','Profil előnézete',p.id)}${button('approve','Jóváhagyás',p.id)}${button('reject','Elutasítás',p.id)}${button('suspend','Felfüggesztés',p.id)}</div></div>`).join('')||empty('Nincs találat.','Módosítsd az adminisztrátori keresést.',null)}<p class="demo-caption">${Math.min(30,profiles.length)} / ${profiles.length} profil. Kereséssel minden profil elérhető.</p></div>`;}
if(accountTab==='reports')return `<div class="panel"><h3>Tartalomjelentések · demó</h3>${state.reports.length?state.reports.map(r=>`<div class="record"><div class="record-head"><div><h3>${esc(getProfile(r.profileId)?.name??'Archív profil')}</h3><p>${esc(r.reason)} · ${esc(r.text)}</p><small>${esc(r.date)} · ${r.reviewId?'Vélemény':'Profil'} jelentése</small></div><span class="status">${r.resolved?'Lezárva · demó':'Új · demó'}</span></div>${!r.resolved?button('resolve-report','Jelentés lezárása',r.id):''}</div>`).join(''):empty('Minden nyugodt.','A profilokon és véleményeken leadott demójelentések itt jelennek meg.',null)}</div>`;
if(accountTab==='reviews'){const list=all().flatMap(p=>p.reviews.map(r=>({...r,profileName:p.name}))).filter(r=>!adminQuery||D.fold(r.profileName+' '+r.text).includes(D.fold(adminQuery)));return `<div class="panel"><h3>Fiktív vélemények moderálása</h3><form id="admin-search"><div class="form-grid">${field('adminQuery','Profil vagy véleményszöveg keresése','text',adminQuery)}<div class="modal-actions"><button type="submit">Keresés</button>${button('admin-clear','Törlés')}</div></div></form>${list.slice(0,30).map(r=>`<div class="record"><h3>${esc(r.profileName)} <span class="rating">★ ${r.rating}</span></h3><p>${esc(r.text)}</p><small>${esc(r.name)} · Szimulált vélemény · ${state.reviewModeration[r.id]?'Rejtett':'Látható'}</small><div class="record-actions">${button('toggle-review',state.reviewModeration[r.id]?'Visszaállítás':'Elrejtés',r.id)}</div></div>`).join('')}<p class="demo-caption">${Math.min(30,list.length)} / ${list.length} vélemény; kereséssel minden tétel elérhető.</p></div>`;}
if(accountTab==='campaigns')return `<div class="split"><div class="panel"><h3>Promóciós kampányok · demó</h3><form id="campaign-form"><div class="form-grid">${field('code','Új promóciós kód','text','','required pattern="[A-Za-z0-9]{3,20}" maxlength="20"')}${field('discount','Kedvezmény százalék','number',10,'required min="1" max="50" step="1"')}</div><div class="modal-actions"><button type="submit" class="gold">Kampány létrehozása</button></div></form>${state.campaigns.map(c=>`<div class="record"><div class="record-head"><span>${esc(c.code)} · ${Math.round(c.discount*100)}% · ${c.active?'Aktív':'Inaktív'}</span>${button('toggle-campaign',c.active?'Leállítás':'Aktiválás',c.code)}</div></div>`).join('')}</div><div class="panel"><h3>Demókategóriák kezelése</h3><form id="category-form">${field('categoryName','Új kategória neve','text','','required minlength="3" maxlength="40"')}<div class="modal-actions"><button type="submit" class="gold">Kategória hozzáadása</button></div></form>${state.categories.map(c=>`<div class="record"><div class="record-head"><span>${esc(c)}</span>${button('delete-category','Törlés',c)}</div></div>`).join('')}<small>Használatban lévő kategória nem törölhető.</small></div></div>`;
if(accountTab==='finance'){const gross=state.transactions.filter(t=>['booking','membership','promotion'].includes(t.type)).reduce((n,t)=>n-t.amount,0),refunds=state.transactions.filter(t=>t.type==='refund').reduce((n,t)=>n+t.amount,0);return stats([['Virtuális költés',`${money(gross)} kr`],['Virtuális visszatérítés',`${money(refunds)} kr`],['Nettó demóforgalom',`${money(gross-refunds)} kr`],['Demófiók',state.users.length]])+`<div class="panel"><h3>Virtuális forgalom kategóriánként</h3>${chart(['booking','membership','promotion','refund'].map(type=>[({booking:'Foglalás',membership:'Tagság',promotion:'Kiemelés',refund:'Visszatérítés'})[type],state.transactions.filter(t=>t.type===type).reduce((n,t)=>n+Math.abs(t.amount),0)]))}<p class="demo-caption">Szimulált kreditek. Nincs valódi bevétel vagy pénzügyi elszámolás.</p></div><div class="panel"><h3>Minden szimulált tranzakció</h3>${transactionTable(state.transactions)}</div><div class="panel"><h3>Demófoglalások kezelése</h3>${bookingRecords(state.bookings,u)}</div>`;}
if(accountTab==='audit')return `<div class="panel"><h3>Demóműveletek auditnaplója</h3><p>Legfeljebb 500 helyi művelet. A napló csak szemléltetés, a böngésző tulajdonosa módosíthatja.</p>${state.audit.length?`<div class="table-wrap"><table><thead><tr><th>Időpont</th><th>Demófelhasználó</th><th>Művelet</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${esc(new Date(a.date).toLocaleString('hu-HU'))}</td><td>${esc(state.users.find(u=>u.id===a.user)?.name??'Látogató')}</td><td>${esc(a.action)}</td></tr>`).join('')}</tbody></table></div>`:empty('Még nincs naplózott művelet.','A mentett demóváltoztatások itt jelennek meg.',null)}</div>`;
return '';}
function bookingRecords(bookings,u){return bookings.length?bookings.map(b=>`<div class="record"><div class="record-head"><div><h3>${esc(b.profileName)}</h3><p>${esc(b.category)} · ${esc(b.package)} · ${b.duration} óra</p><p>${dateLabel(b.date)} · ${b.time} · <span class="price">${money(b.total)} kr</span></p><small>${esc(b.id)} · Szimulált foglalás</small></div><span class="status ${b.status}">${esc(statusText[b.status])}</span></div><div class="record-actions">${['confirmed','requested'].includes(b.status)?button('cancel-confirm',u.role==='advertiser'?'Elutasítás és visszatérítés':'Lemondás és visszatérítés',b.id):''}${['admin','advertiser'].includes(u.role)&&b.status==='confirmed'?button('complete-booking','Teljesített státusz · demó',b.id):''}${state.transactions.find(t=>t.bookingId===b.id&&t.type==='booking')?button('receipt','Demóbizonylat',state.transactions.find(t=>t.bookingId===b.id&&t.type==='booking').id):''}${getProfile(b.profileId)?.status==='approved'?button('profile','Profil',b.profileId):''}</div></div>`).join(''):empty('Még nincs demófoglalás.','Az itt megjelenő foglalások kizárólag szimuláltak.',u.role==='customer'?'discover':null);}
function transactionTable(transactions){return transactions.length?`<div class="table-wrap"><table><thead><tr><th>Dátum</th><th>Tétel</th><th>Demókredit</th><th>Státusz</th><th>Bizonylat</th></tr></thead><tbody>${transactions.map(t=>`<tr><td>${esc(new Date(t.date).toLocaleDateString('hu-HU'))}</td><td>${esc(t.label)}</td><td class="${t.amount>0?'success':'muted'}">${t.amount>0?'+':''}${money(t.amount)} kr</td><td>${esc(t.status)}</td><td>${button('receipt','Letöltés',t.id)}</td></tr>`).join('')}</tbody></table></div>`:empty('Még nincs szimulált tranzakció.','A feltöltések, foglalások és visszatérítések itt követhetők.',null);}
function walletModal(){if(!user()){loginModal();return;}modal('A virtuális pénztárcád',`<div class="notice">Kizárólag szimulált kreditek. Nincs pénzbeli értékük. Soha ne adj meg bankkártyaadatot.</div>${stats([['Egyenleg',`${money(user().balance)} kr`],['Hűségpont',user().points],['Demótranzakció',state.transactions.filter(t=>t.userId===user().id).length],['Tagság',user().membership??'Standard']])}<form id="topup-form">${field('amount','Szimulált feltöltés összege','number',10000,'required min="1" max="100000" step="1"')}<div class="modal-actions"><button type="submit" class="gold">Demókreditek jóváírása ↗</button>${button('topup-preset','+5 000 kr','5000')}${button('topup-preset','+25 000 kr','25000')}</div></form><div class="modal-actions">${button('transactions','Tranzakciós előzmények ↗')}${button('membership','Privé Club')}${button('redeem','100 pont → 500 kr')}</div><p class="demo-caption">A feltöltés azonnali fiktív jóváírás, semmilyen fizetési adatot nem kérünk.</p>`,'wallet');}
function messageModal(id){if(!user()){loginModal();return;}const p=getProfile(id);if(!p)throw new Error('Nincs ilyen profil.');const messages=state.messages.filter(m=>m.userId===user().id&&m.profileId===id);modal(`Demóbeszélgetés · ${esc(p.name)}`,`<div class="notice">Böngészőben maradó szimulált üzenetek és automatikus válasz. Nincs valódi címzett. Ne írj személyes adatot vagy elérhetőséget.</div><div>${messages.map(m=>`<div class="message ${m.sender}">${esc(m.text)}<small>${m.sender==='demo'?'Automatikus demókarakter':'Te · demó'} · ${new Date(m.date).toLocaleTimeString('hu-HU',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')||'<p>Még nincs üzenet. Próbáld ki a fiktív beszélgetést.</p>'}</div><form id="message-form" data-id="${id}"><div class="field"><label for="message">Demóüzenet · maximum 500 karakter</label><textarea id="message" name="message" maxlength="500" required placeholder="Például: milyen kiállítást választanál a demóprogramhoz?"></textarea></div><div class="modal-actions"><button type="submit" class="gold">Szimulált küldés ↗</button></div></form>`,'messages');}
function adModal(id=''){D.requireRole(state,['advertiser']);const p=id?state.ads.find(p=>p.id===id&&p.ownerId===user().id):null;if(id&&!p)throw new Error('Csak saját hirdetés szerkeszthető.');adImages=p?.images??[];modal(p?'A fiktív hirdetés szerkesztése':'Új karakter az atelier-ben',`<div class="notice">Csak fiktív, 21 év feletti karaktert hozz létre. Nincs valódi elérhetőség, személyes adat vagy szolgáltatás. Mentés után adminisztrátori demójóváhagyás szükséges.</div><form id="ad-form" data-id="${id}"><div class="form-grid">${field('name','Fiktív karakter neve','text',p?.name??'','required minlength="3" maxlength="60"')}${field('age','Fiktív életkor · 21+','number',p?.age??25,'required min="21" max="70" step="1"')}${selectField('city','Város',['Budapest','Debrecen','Szeged','Pécs','Győr','Sopron','Balatonfüred'],p?.city??'Budapest',null)}${field('district','Kerület / városrész','text',p?.district??'Belváros','required maxlength="30"')}${field('price','Szimulált alap-óradíj · kredit','number',p?.price??3000,'required min="100" max="50000" step="1"')}${field('style','Divat és stílus','text',p?.style??'Kortárs elegancia','required maxlength="100"')}<div class="field full"><label for="bio">Egyedi fiktív bemutatkozás · 30–2000 karakter</label><textarea name="bio" id="bio" required minlength="30" maxlength="2000">${esc(p?.bio??'')}</textarea></div><div class="full"><h3>Programkategóriák</h3><div class="form-grid">${state.categories.map(c=>`<label class="check"><input type="checkbox" name="categories" value="${esc(c)}" ${p?.categories.includes(c)?'checked':''}> ${esc(c)}</label>`).join('')}</div><p class="demo-caption">Minden kiválasztott kategóriára az alap-óradíj érvényes. Essential: +0, Signature: +750, Prestige: +1500 demókredit.</p></div><div class="full"><h3>Heti demóelérhetőség</h3><div class="form-grid">${['Vasárnap','Hétfő','Kedd','Szerda','Csütörtök','Péntek','Szombat'].map((d,i)=>`<label class="check"><input type="checkbox" name="days" value="${i}" ${(p?.availability.days??[1,2,3,4,5]).includes(i)?'checked':''}> ${d} · 14:00–22:00</label>`).join('')}</div></div><div class="field full"><label for="images">Demóképek feltöltése · max. 3 kép, képenként 500 KB (PNG, JPEG, WebP)</label><input id="images" type="file" accept="image/png,image/jpeg,image/webp" multiple><div id="upload-preview" class="upload-preview">${adImages.map(src=>`<img src="${esc(src)}" alt="Feltöltött demókép">`).join('')}</div><p class="demo-caption">Kép nélkül saját fiktív digitális portrét rendelünk a profilhoz.</p></div><label class="check full"><input type="checkbox" name="fictional" required> Minden adat és kép fiktív felnőtt karaktert ábrázol; a képek használatára jogosult vagyok.</label></div><div class="modal-actions"><button type="submit" class="gold">Mentés és beküldés moderálásra ↗</button><button type="submit" name="preview" value="yes">Előnézet készítése</button></div><p class="demo-caption">Az előnézet a formot ellenőrzi és menti, majd a beküldött hirdetést mutatja.</p></form>`,'ad');}
function reportModal(id,reviewId=''){modal('Tartalomjelentés · demó',`<div class="notice">A jelentés az adott böngésző adminisztrátori demónézetében jelenik meg. Nem küldjük el valódi moderátornak.</div><form id="report-form" data-id="${esc(id)}" data-review="${esc(reviewId)}">${selectField('reason','Jelentés oka',['Korhatárral kapcsolatos aggály','Nem megfelelő tartalom','Megtévesztő demóadat','Képhasználat','Egyéb'],'Nem megfelelő tartalom',null)}<div class="field margin-top"><label for="reportText">Rövid indoklás · személyes adat nélkül</label><textarea id="reportText" name="reportText" required maxlength="500"></textarea></div><div class="modal-actions"><button type="submit" class="gold">Demójelentés rögzítése ↗</button></div></form>`,'report');}
function backupModal(){modal('A demóadataid a kezedben',`<div class="notice">A mentés demójelszavakat, helyi fiókokat és üzeneteket tartalmaz. Csak saját demóadatot exportálj és importálj. Valódi jelszót vagy személyes adatot ne használj!</div><div class="modal-actions">${button('export','JSON demómentés letöltése','','gold')}${button('recovery-export','Sérült adat biztonsági példánya')}</div><form id="import-form" class="margin-top"><div class="field"><label for="backupFile">Demómentés visszaállítása · JSON, max. 10 MB</label><input id="backupFile" name="backupFile" type="file" accept="application/json,.json" required></div><label class="check margin-top"><input name="replace" type="checkbox" required> A jelenlegi demóadatokat a kiválasztott mentésre cserélem.</label><div class="modal-actions"><button type="submit">Ellenőrzött importálás</button>${button('reset-confirm','Demó alaphelyzetbe állítása','','danger')}</div></form><p class="demo-caption">Sémaellenőrzés, 1→2 verziómigráció, sérült adatok elkülönített mentése. A nagy képfeltöltések növelik az export méretét.</p>`,'backup');}
function legalModal(){modal('Tudatos demóhasználat',`<h3>Kizárólag fiktív felnőtt világ</h3><p>Minden karakter legalább 21 éves. Minden profil, kép, értékelés, üzenet, ellenőrzés, foglalás és tranzakció fiktív vagy szimulált. A programkategóriák kizárólag kulturális és társasági demóélményeket szemléltetnek. Nincs valódi szolgáltatás vagy találkozószervezés.</p><h3>Adatok a saját böngésződben</h3><p>A fiókok, demójelszavak, foglalások, kreditek és üzenetek IndexedDB-ben tárolódnak. Ezek nem valódi hitelesítési vagy biztonsági mechanizmusok. A böngésző tulajdonosa az adatokat módosíthatja. A feltöltött képek nem kerülnek szerverre. A webhely nem használ analitikai követést vagy reklámsütiket.</p><p>A GitHub Pages a statikus fájlok kiszolgálásakor a saját adatkezelési szabályai szerint kezelhet hálózati naplóadatokat. Az életkor-nyilatkozat sessionStorage-ben, a lap munkamenetére marad meg. Ez nem életkor-igazolás.</p><h3>Fiktív kreditrendszer</h3><p>Nincs bankkártyaadat, valódi fizetés, pénzváltás vagy kifizetés. A bizonylatok nem adóügyi dokumentumok. A tagságok egyszeri demóműveletek; nincs valódi előfizetés.</p><h3>Tartalom és képhasználat</h3><p>A beépített portrék e projekthez létrehozott eredeti, stilizált SVG-illusztrációk. Nem valódi személyek fotói. Feltöltéskor csak jogszerűen használható, fiktív felnőtt karakterképet válassz. Valódi személyes adatot és elérhetőséget ne adj meg.</p><p>A Profil jelentése és Vélemény jelentése funkció a helyi demóadminisztráció számára rögzíti a bejelentést.</p><div class="modal-actions">${button('backup','Adatmentés és törlés')}${button('exit-gate','Korhatár-nyilatkozat visszavonása')}</div>`,'legal');}
async function handleAction(el){const action=el.dataset.action,id=el.dataset.id??'';
switch(action){
case 'close':close();break;
case 'discover':case 'membership':case 'favorites':case 'recent':case 'compare':close();navigate(action);window.scrollTo({top:0,behavior:'smooth'});break;
case 'browse':if(route()!=='discover')navigate('discover');$('#collection')?.scrollIntoView({behavior:'smooth'});break;
case 'profile':await openProfile(id);break;
case 'gallery':{const p=getProfile(id);$('#gallery-image').src=p.images[Number(el.dataset.index)];$('#gallery-image').alt=`${p.name} — ${Number(el.dataset.index)+1}. digitális demóportré`;break;}
case 'favorite':await change(s=>{s.favorites=s.favorites.includes(id)?s.favorites.filter(x=>x!==id):[...s.favorites,id];},{render:!$('#modal').open,message:state.favorites.includes(id)?'Profil eltávolítva a kedvencekből.':'Fiktív profil a kedvencek közé mentve.'});if(modalKind==='profile')await openProfile(id,false);break;
case 'category':filters.category=id;limit=12;renderPage();$('#collection')?.scrollIntoView({block:'start'});break;
case 'advanced':captureFilters();advanced=!advanced;renderPage();$('#collection')?.scrollIntoView({block:'start'});break;
case 'reset-filters':filters={};limit=12;renderPage();$('#collection')?.scrollIntoView({block:'start'});break;
case 'load-more':{const y=window.scrollY;limit+=12;renderPage();window.scrollTo(0,y);break;}
case 'save-search':captureFilters();await change(s=>{if(s.savedSearches.length>=10)throw new Error('Legfeljebb 10 keresés menthető.');s.savedSearches.push({name:`${filters.city||'Minden város'} · ${filters.category||filters.q||'Kollekció'}${filters.premium?' · Privé':''}`,filters:structuredClone(filters)});},{message:'Keresés ezen a böngészőn elmentve.'});break;
case 'saved-search':filters=structuredClone(state.savedSearches[Number(id)].filters);limit=12;renderPage();$('#collection')?.scrollIntoView();break;
case 'delete-search':await change(s=>s.savedSearches.splice(Number(id),1));break;
case 'suggestion':filters.q=id;renderPage();$('#collection')?.scrollIntoView();break;
case 'clear-recent':await change(s=>s.recent=[]);break;
case 'clear-compare':await change(s=>s.compare=[]);break;
case 'remove-compare':await change(s=>s.compare=s.compare.filter(x=>x!==id));break;
case 'login':if(user()){close();navigate('account');}else loginModal();break;
case 'register':loginModal(true);break;
case 'demo-login':await change(s=>D.demoLogin(s,id),{render:false,message:'Demószerepkör aktiválva. Ez nem valódi hitelesítés.'});accountTab='overview';close();navigate('account');break;
case 'logout':await change(s=>{D.audit(s,'Kilépés');s.session=null;},{message:'Kiléptél a demófiókból.'});break;
case 'account-tab':accountTab=id;adminQuery='';renderPage();break;
case 'book':bookingModal(id);break;
case 'booking-back':renderBooking(1);break;
case 'pay':{if(!$('#payment-consent').checked)throw new Error('Előbb fogadd el a szimulált tranzakció jellegét.');const draft={...bookingDraft};el.disabled=true;el.textContent='Szimulált fizetés mentése…';try{const b=await change(s=>D.book(s,getProfile(draft.profileId),draft),{render:false});bookingDraft={...draft,confirmation:b};renderBooking(3);toast('A szimulált fizetés sikeres. Valódi terhelés nem történt.');}catch(e){el.disabled=false;el.textContent='Szimulált fizetés újrapróbálása';throw e;}break;}
case 'history':close();accountTab='bookings';navigate('account');break;
case 'transactions':close();accountTab='transactions';navigate('account');break;
case 'wallet':walletModal();break;
case 'topup-preset':await change(s=>D.wallet(s,Number(id)),{render:false,message:'Virtuális kreditek jóváírva. Valódi fizetés nincs.'});walletModal();break;
case 'receipt':{const t=state.transactions.find(t=>t.id===id);if(!t||!user()||(t.userId!==user().id&&user().role!=='admin'))throw new Error('Ehhez a bizonylathoz nincs demójogosultság.');download(`NOIR-DEMO-${t.id.slice(0,8)}.txt`,D.receipt(t));toast('Szimulált bizonylat letöltve.');break;}
case 'cancel-confirm':{const b=state.bookings.find(b=>b.id===id);modal('Demófoglalás lemondása',`<p>${esc(b.profileName)} · ${dateLabel(b.date)} · ${b.time}</p><div class="notice">${money(b.total)} demókredit teljes virtuális visszatérítését szimuláljuk. A foglalás hűségpontjait visszavonjuk.</div><div class="modal-actions">${button('cancel','Lemondás és szimulált visszatérítés',id,'gold')}${button('close','Mégsem','','quiet')}</div>`);break;}
case 'cancel':await change(s=>D.cancel(s,id,{reject:user()?.role==='advertiser'}),{message:'Demófoglalás lemondva, kreditek visszatérítve.'});close();break;
case 'complete-booking':await change(s=>D.updateBooking(s,id,'completed'),{message:'Szimulált teljesített státusz mentve.'});break;
case 'membership-confirm':{if(!user()){loginModal();break;}const m=D.MEMBERSHIPS.find(m=>m.id===id);if(user().membership===id){toast('Ez a demótagság már aktív.');break;}modal(`${m.name} demótagság`, `<div class="notice">${money(m.price)} virtuális kredit egyszeri levonása. Nincs valódi fizetés vagy előfizetés.</div><p>${Math.round(m.discount*100)}% kedvezmény a későbbi demófoglalásokra. Tagságváltáskor a korábbi díj nem térül vissza.</p><div class="modal-actions">${button('buy-membership','Szimulált tagság aktiválása',id,'gold')}${button('close','Mégsem','','quiet')}</div>`);break;}
case 'buy-membership':await change(s=>D.buyMembership(s,id),{message:'Prémium demótagság aktiválva.'});close();break;
case 'redeem':await change(s=>D.redeem(s),{render:!$('#modal').open,message:'100 demópont beváltva: +500 virtuális kredit.'});if(modalKind==='wallet')walletModal();break;
case 'message':messageModal(id);break;
case 'new-ad':adModal();break;
case 'edit-ad':adModal(id);break;
case 'promote-confirm':{const p=state.ads.find(p=>p.id===id);if(p?.premium){toast('Ez a demókiemelés már aktív.');break;}modal('Privé Selection · demókiemelés','<p>1 000 virtuális kreditért a saját fiktív hirdetésed kiemelt státuszt kap. Az ajánlott sorrendben a prémium profilok előrébb kerülnek.</p><div class="modal-actions">'+button('promote','Szimulált kiemelés megvásárlása',id,'gold')+button('close','Mégsem','','quiet')+'</div>');break;}
case 'promote':await change(s=>D.promote(s,id),{message:'Fiktív hirdetés kiemelve.'});close();break;
case 'approve':case 'reject':case 'suspend':await change(s=>D.moderate(s,id,({approve:'approved',reject:'rejected',suspend:'suspended'})[action],all()),{message:'Demómoderálás mentve.'});break;
case 'admin-clear':adminQuery='';renderPage();break;
case 'report':reportModal(id);break;
case 'report-review':{const [p,r]=id.split('|');reportModal(p,r);break;}
case 'resolve-report':await change(s=>{D.requireRole(s,['admin']);const r=s.reports.find(r=>r.id===id);r.resolved=true;D.audit(s,'Demójelentés lezárva');},{message:'Demójelentés lezárva.'});break;
case 'toggle-review':await change(s=>{D.requireRole(s,['admin']);s.reviewModeration[id]=!s.reviewModeration[id];D.audit(s,`Fiktív vélemény ${s.reviewModeration[id]?'elrejtve':'visszaállítva'}`);});break;
case 'toggle-campaign':await change(s=>{D.requireRole(s,['admin']);const c=s.campaigns.find(c=>c.code===id);c.active=!c.active;D.audit(s,`Kampány ${c.code}: ${c.active?'aktív':'inaktív'}`);});break;
case 'delete-category':await change(s=>{D.requireRole(s,['admin']);if(all().some(p=>p.categories.includes(id)))throw new Error('Használatban lévő kategória nem törölhető.');s.categories=s.categories.filter(c=>c!==id);D.audit(s,'Demókategória törölve');});break;
case 'notifications':{if(!user()){loginModal();break;}const notices=state.notifications.filter(n=>n.userId===user().id);await change(s=>{s.notifications.filter(n=>n.userId===s.session).forEach(n=>n.read=true);},{render:false});modal('Privé értesítések',notices.length?notices.map(n=>`<div class="record"><p>${esc(n.text)}</p><small>${esc(new Date(n.date).toLocaleString('hu-HU'))} · Szimulált értesítés</small></div>`).join(''):empty('Nincs új demóértesítés.','Foglalás, feltöltés vagy szimulált üzenet után itt jelenik meg értesítés.',null));break;}
case 'verification':modal('Átlátható demóellenőrzés','<div class="notice">A pipa kizárólag a felület demonstrációja.</div><p>Nem történt valódi személyazonosság-, életkor- vagy fényképellenőrzés. A beépített karakterek mind fiktívek és legalább 21 évesek. Az adminisztrátori jóváhagyás is csak szimuláció.</p>');break;
case 'legal':legalModal();break;
case 'backup':backupModal();break;
case 'export':download('noir-prive-demo-backup.json',JSON.stringify(state,null,2),'application/json');toast('Demómentés letöltve.');break;
case 'recovery-export':{const raw=await store.recovery();if(!raw)throw new Error('Nincs elkülönített sérült demómentés.');download('noir-prive-corrupt-backup.json',JSON.stringify(raw,null,2),'application/json');break;}
case 'reset-confirm':modal('Új fejezet, tiszta lappal','<div class="notice">Minden helyi demófiók, kredit, foglalás, kép, üzenet, kedvenc és mentett keresés törlődik. A 216 eredeti fiktív karakter megmarad.</div><p>Előtte készíthetsz JSON biztonsági mentést.</p><div class="modal-actions">'+button('export','Mentés letöltése')+button('reset','Minden demóadat törlése','','danger')+button('close','Mégsem','','quiet')+'</div>');break;
case 'reset':{const r=await store.reset();state=r.state;filters={};accountTab='overview';close();updateHeader();navigate('discover');toast('A demó alaphelyzetbe állítva.');break;}
case 'exit-gate':close();sessionStorage.removeItem('noir-adult');$('#adult-check').checked=false;$('#enter').disabled=true;$('#age-gate').showModal();break;
}
}
function captureFilters(){const form=$('#search-form');if(!form)return;const data=new FormData(form);for(const k of ['q','city','district','minAge','maxAge','minPrice','maxPrice','date','rating'])if(data.has(k))filters[k]=data.get(k);if(advanced){filters.premium=data.has('premium');filters.verified=data.has('verified');}}
async function onSubmit(e){e.preventDefault();const form=e.target,data=new FormData(form);try{switch(form.id){
case 'search-form':captureFilters();if(Number(filters.minAge||21)>Number(filters.maxAge||70)||Number(filters.minPrice||0)>Number(filters.maxPrice||100000))throw new Error('A minimum nem lehet nagyobb a maximumnál.');limit=12;renderPage();$('#collection')?.scrollIntoView({behavior:'smooth'});break;
case 'login-form':await change(s=>D.login(s,data.get('handle'),data.get('password')),{render:false});close();accountTab='overview';navigate('account');toast('Sikeres demóbelépés.');break;
case 'register-form':await change(s=>D.register(s,{name:data.get('name'),handle:data.get('handle'),password:data.get('password'),role:data.get('role'),adult:data.has('adult')}),{render:false});close();accountTab='overview';navigate('account');toast('Demófiók létrehozva: 25 000 virtuális kredit.');break;
case 'booking-form':{bookingDraft={...bookingDraft,...Object.fromEntries(data),duration:Number(data.get('duration'))};const p=getProfile(bookingDraft.profileId);D.calculate(p,{...bookingDraft,membership:user().membership},state.campaigns);if(!D.isAvailable(p,bookingDraft.date,bookingDraft.time,bookingDraft.duration,state.bookings))throw new Error('Válassz a teljes időtartamra elérhető kezdést.');renderBooking(2);break;}
case 'topup-form':await change(s=>D.wallet(s,Number(data.get('amount'))),{render:false,message:'Szimulált feltöltés sikeres.'});walletModal();break;
case 'message-form':await change(s=>D.sendMessage(s,getProfile(form.dataset.id),data.get('message')),{render:false});messageModal(form.dataset.id);toast('Szimulált üzenet és automatikus válasz mentve.');break;
case 'ad-form':{if(!data.has('fictional'))throw new Error('Fogadd el a fiktív képek és karakterek feltételét.');const input={...Object.fromEntries(data),id:form.dataset.id||null,categories:data.getAll('categories'),days:data.getAll('days'),images:adImages};if(/@|https?:|\+?\d[\d\s-]{6,}/i.test(input.bio+' '+input.name))throw new Error('Ne adj meg valódi elérhetőséget a fiktív hirdetésben.');const p=await change(s=>D.saveAd(s,input,catalog),{render:false});close();accountTab='ads';navigate('account');toast('Fiktív hirdetés mentve, demómoderálásra vár.');if(e.submitter?.name==='preview')await openProfile(p.id);break;}
case 'admin-search':D.requireRole(state,['admin']);adminQuery=String(data.get('adminQuery'));renderPage();break;
case 'report-form':await change(s=>{if(s.reports.length>=200)throw new Error('A jelentések demókorlátját elérted.');s.reports.unshift({id:D.uid(),profileId:form.dataset.id,reviewId:form.dataset.review||null,reason:data.get('reason'),text:String(data.get('reportText')).slice(0,500),date:new Date().toISOString(),resolved:false});D.audit(s,'Szimulált tartalomjelentés');},{render:false});close();toast('A jelentés a helyi demóadmin nézetbe került.');break;
case 'campaign-form':await change(s=>{D.requireRole(s,['admin']);const code=String(data.get('code')).trim().toUpperCase(),discount=Number(data.get('discount'))/100;if(!/^[A-Z0-9]{3,20}$/.test(code)||discount<=0||discount>.5)throw new Error('Érvénytelen kampányadat.');if(s.campaigns.some(c=>c.code===code))throw new Error('Ez a kód már létezik.');s.campaigns.push({code,discount,active:true});D.audit(s,'Új promóciós demókampány');},{message:'Demókampány létrehozva.'});break;
case 'category-form':await change(s=>{D.requireRole(s,['admin']);const c=String(data.get('categoryName')).trim();if(c.length<3||c.length>40||s.categories.some(x=>D.fold(x)===D.fold(c)))throw new Error('A kategória legyen egyedi, 3–40 karakter.');s.categories.push(c);D.audit(s,'Demókategória létrehozva');},{message:'Új kategória mentve.'});break;
case 'import-form':{const file=$('#backupFile').files[0];if(!data.has('replace')||!file||file.size>10*1024*1024)throw new Error('Válassz legfeljebb 10 MB-os JSON mentést és fogadd el a cserét.');let raw;try{raw=JSON.parse(await file.text());}catch{throw new Error('A fájl nem érvényes JSON.');}D.validateState(raw);const r=await store.replace(raw);state=r.state;close();updateHeader();renderPage();toast('Demómentés ellenőrizve és visszaállítva.');break;}
}}catch(error){showError(error);}}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target){e.preventDefault();handleAction(target).catch(showError);}});
document.addEventListener('submit',onSubmit);
document.addEventListener('input',e=>{
if(e.target.id==='q'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const q=e.target.value;const box=$('#suggestions');if(box)box.innerHTML=q.length>=2?all().filter(p=>p.status==='approved'&&D.fold(p.name+' '+p.city).includes(D.fold(q))).slice(0,4).map(p=>button('suggestion',esc(p.name),p.name)).join(''):'';},150);}
if(e.target.closest('#booking-form')&&['code','duration','packageId','category'].includes(e.target.name)){bookingDraft={...bookingDraft,...Object.fromEntries(new FormData($('#booking-form'))),duration:Number($('#duration').value)};if(e.target.name==='duration'){renderBooking(1);}else $('#live-quote').innerHTML=quoteHtml();}
});
document.addEventListener('change',async e=>{try{
if(e.target.dataset.compare){const id=e.target.dataset.compare;await change(s=>{if(s.compare.includes(id))s.compare=s.compare.filter(x=>x!==id);else{if(s.compare.length>=4)throw new Error('Legfeljebb négy profil hasonlítható össze.');s.compare.push(id);}},{render:false});renderDock();}
if(e.target.id==='sort'){filters.sort=e.target.value;const y=window.scrollY;renderPage();window.scrollTo(0,y);}
if(e.target.id==='city'&&e.target.closest('#search-form')){captureFilters();filters.district='';renderPage();$('#collection')?.scrollIntoView();}
if(e.target.id==='date'&&e.target.closest('#booking-form')){bookingDraft={...bookingDraft,...Object.fromEntries(new FormData($('#booking-form'))),time:'',duration:Number($('#duration').value)};renderBooking(1);}
if(e.target.id==='images'){const files=[...e.target.files];if(files.length>3)throw new Error('Legfeljebb három demókép tölthető fel.');const results=[];for(const file of files){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>500*1024)throw new Error('Csak PNG/JPEG/WebP képet válassz, legfeljebb 500 KB mérettel.');const src=await new Promise((res,rej)=>{const reader=new FileReader();reader.onload=()=>res(reader.result);reader.onerror=()=>rej(new Error('A kép olvasása sikertelen.'));reader.readAsDataURL(file);});await new Promise((res,rej)=>{const img=new Image();img.onload=()=>res();img.onerror=()=>rej(new Error('A feltöltött fájl nem érvényes kép.'));img.src=src;});results.push(src);}adImages=results;$('#upload-preview').innerHTML=results.map(src=>`<img src="${esc(src)}" alt="Demókép előnézete">`).join('');}
}catch(error){if(e.target.dataset.compare)e.target.checked=state.compare.includes(e.target.dataset.compare);if(e.target.id==='images')e.target.value='';showError(error);}});
$('#modal').addEventListener('cancel',()=>{modalKind='';bookingDraft=null;});
$('#age-gate').addEventListener('cancel',e=>e.preventDefault());
$('#adult-check').addEventListener('change',e=>$('#enter').disabled=!e.target.checked);
$('#enter').addEventListener('click',()=>{if($('#adult-check').checked){try{sessionStorage.setItem('noir-adult','yes');}catch{}$('#age-gate').close();}});
$('#decline').addEventListener('click',()=>{$('#age-error').textContent='A belépés elutasítva. A demó csak 18 év feletti nyilatkozattal használható. Ezt a lapot biztonságosan bezárhatod.';$('#adult-check').checked=false;$('#enter').disabled=true;});
window.addEventListener('hashchange',()=>{close();renderPage();window.scrollTo(0,0);});
store.onChange=async()=>{try{state=await store.read();updateHeader();renderPage();if($('#modal').open){close();toast('A demóadatok egy másik lapon frissültek. Nyisd meg újra a műveletet.');}}catch(e){toast(e.message,true);}};
async function init(){try{let accepted=false;try{accepted=sessionStorage.getItem('noir-adult')==='yes';}catch{}if(!accepted)$('#age-gate').showModal();const [saved,response]=await Promise.all([store.open(),fetch('./profiles.json')]);if(!response.ok)throw new Error('A katalógus nem tölthető be.');catalog=await response.json();if(!Array.isArray(catalog)||catalog.length<200||catalog.some(p=>p.age<21))throw new Error('A katalógus ellenőrzése sikertelen.');state=saved;updateHeader();renderPage();}catch(e){$('#main').innerHTML=empty('A kollekció nem tölthető be.',e.message,null);toast('Betöltési hiba. Töltsd újra az oldalt.',true);}}
init();
